/// One of the 14 mods VOID ships — the closed `mod_id` enum of `schema/mods.json`.
///
/// Used as the key of `loadout.mods`, as the `id` argument of `void.setModSetting`, and as the
/// id of a HUD item.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ModId {
    /// Frames per second, updated once per tick.
    Fps,
    /// WASD, mouse and spacebar tiles that light up as you press them.
    Keystrokes,
    /// Clicks per second over a sliding window.
    Cps,
    /// Round-trip time to the current server.
    Ping,
    /// Player position and facing direction.
    Coordinates,
    /// Worn armor and held item with remaining durability.
    ArmorStatus,
    /// Active potion effects with amplifier and remaining duration.
    PotionEffects,
    /// The VOID mark, drawn over the game.
    Watermark,
    /// Latches sprint instead of holding the key.
    ToggleSprint,
    /// Raises gamma so caves and shadows are fully lit.
    Fullbright,
    /// Draws entity bounding boxes.
    Hitboxes,
    /// Narrows FOV while the zoom key is held.
    Zoom,
    /// Replaces the vanilla crosshair with a configurable one at the exact screen centre.
    Crosshair,
    /// Which way you are facing, as its own placeable readout.
    Direction,
}

impl ModId {
    /// Every mod id, in registry order.
    pub const ALL: [ModId; 14] = [
        ModId::Fps,
        ModId::Keystrokes,
        ModId::Cps,
        ModId::Ping,
        ModId::Coordinates,
        ModId::ArmorStatus,
        ModId::PotionEffects,
        ModId::Watermark,
        ModId::ToggleSprint,
        ModId::Fullbright,
        ModId::Hitboxes,
        ModId::Zoom,
        ModId::Crosshair,
        ModId::Direction,
    ];

    /// The snake_case id used as a `loadout.mods` key and in `mods.<id>.<key>` paths.
    pub fn as_str(self) -> &'static str {
        match self {
            ModId::Fps => "fps",
            ModId::Keystrokes => "keystrokes",
            ModId::Cps => "cps",
            ModId::Ping => "ping",
            ModId::Coordinates => "coordinates",
            ModId::ArmorStatus => "armor_status",
            ModId::PotionEffects => "potion_effects",
            ModId::Watermark => "watermark",
            ModId::ToggleSprint => "toggle_sprint",
            ModId::Fullbright => "fullbright",
            ModId::Hitboxes => "hitboxes",
            ModId::Zoom => "zoom",
            ModId::Crosshair => "crosshair",
            ModId::Direction => "direction",
        }
    }
}

/// The subset of [`ModId`] whose `kind` is `hud`: the 9 mods that own a draggable HUD item.
///
/// A mod may only appear in `loadout.hud` if it is listed here.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum HudModId {
    /// Frames per second, updated once per tick.
    Fps,
    /// WASD, mouse and spacebar tiles that light up as you press them.
    Keystrokes,
    /// Clicks per second over a sliding window.
    Cps,
    /// Round-trip time to the current server.
    Ping,
    /// Player position and facing direction.
    Coordinates,
    /// Worn armor and held item with remaining durability.
    ArmorStatus,
    /// Active potion effects with amplifier and remaining duration.
    PotionEffects,
    /// The VOID mark, drawn over the game.
    Watermark,
    /// Which way you are facing, as its own placeable readout.
    Direction,
}

impl HudModId {
    /// Every HUD mod id, in registry order.
    pub const ALL: [HudModId; 9] = [
        HudModId::Fps,
        HudModId::Keystrokes,
        HudModId::Cps,
        HudModId::Ping,
        HudModId::Coordinates,
        HudModId::ArmorStatus,
        HudModId::PotionEffects,
        HudModId::Watermark,
        HudModId::Direction,
    ];

    /// Widens to the full mod id enum.
    pub fn as_mod_id(self) -> ModId {
        match self {
            HudModId::Fps => ModId::Fps,
            HudModId::Keystrokes => ModId::Keystrokes,
            HudModId::Cps => ModId::Cps,
            HudModId::Ping => ModId::Ping,
            HudModId::Coordinates => ModId::Coordinates,
            HudModId::ArmorStatus => ModId::ArmorStatus,
            HudModId::PotionEffects => ModId::PotionEffects,
            HudModId::Watermark => ModId::Watermark,
            HudModId::Direction => ModId::Direction,
        }
    }

    /// Narrows a mod id, returning `None` for a gameplay mod.
    pub fn from_mod_id(id: ModId) -> Option<Self> {
        HudModId::ALL.into_iter().find(|m| m.as_mod_id() == id)
    }

    /// The snake_case id.
    pub fn as_str(self) -> &'static str {
        self.as_mod_id().as_str()
    }
}

