/// One of the five unpressed-key swatches on the Mod settings frame, named by the design token
/// it resolves to (`--bg-shell`, `--surface-2`, `--surface-3`, `--sky`, `--teal`). A name
/// rather than a hex value so the choice survives a theme change.
///
/// `mods.json#/definitions/key_swatch`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum KeySwatch {
    /// `shell`.
    Shell,
    /// `raised`.
    Raised,
    /// `pill`.
    Pill,
    /// `sky`.
    Sky,
    /// `teal`.
    Teal,
}

/// One of the five pressed-key swatches on the Mod settings frame, named by the design token it
/// resolves to (`--accent`, `--sky`, `--warn`, `--danger`, `--teal`). `accent` is the frame's
